from __future__ import annotations
import base64, hashlib, json, sys, zlib
from pathlib import Path

# Compressed binary delta generated from the exact RC48 field package:
# base payload/d3d11.dll -> installed RC41/RC48 overlay d3d11.dll.
# The source base SHA and reconstructed output SHA are verified before use.
DATA = ''''''

def sha(b: bytes) -> str:
    return hashlib.sha256(b).hexdigest()

def main() -> None:
    if len(sys.argv) != 3:
        raise SystemExit('usage: rebuild_exact_field_runtime.py BASE_DLL OUTPUT_DLL')
    base_path, out_path = map(Path, sys.argv[1:])
    meta = json.loads(zlib.decompress(base64.b64decode(DATA)).decode('utf-8'))
    raw = bytearray(base_path.read_bytes())
    if len(raw) != meta['base_size'] or sha(raw) != meta['base_sha']:
        raise SystemExit(f"base mismatch size={len(raw)} sha={sha(raw)}")
    for off, payload in meta['ranges']:
        chunk = base64.b64decode(payload)
        raw[off:off+len(chunk)] = chunk
    raw.extend(base64.b64decode(meta['append']))
    if len(raw) != meta['out_size'] or sha(raw) != meta['out_sha']:
        raise SystemExit(f"output mismatch size={len(raw)} sha={sha(raw)}")
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_bytes(raw)
    print(f"EXACT_FIELD_RUNTIME=PASS size={len(raw)} sha256={sha(raw)}")

if __name__ == '__main__':
    main()
